css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .66); position: relative; overflow: hidden; }
.loader .dirty { position: absolute; left: 0; right: 0; bottom: 4%; height: 24%; border-radius: 4px; background: color-mix(in srgb, var(--accent) 18%, transparent); }
.loader .clean { position: absolute; left: 0; bottom: 4%; height: 24%; width: 0; border-radius: 4px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent-2) 60%, transparent) 0 8%, color-mix(in srgb, var(--accent-2) 30%, transparent) 0 16%); animation: vac-clean calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .unit { position: absolute; left: 2%; bottom: 4%; width: 26%; height: 84%; animation: vac-push calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .handle { position: absolute; left: 58%; top: 0; width: 14%; height: 76%; border-radius: 4px; background: linear-gradient(90deg, var(--accent-2), var(--accent)); transform: rotate(12deg); transform-origin: 50% 100%; }
.loader .head { position: absolute; left: 0; bottom: 0; width: 100%; height: 26%; border-radius: 5px; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.loader i { position: absolute; bottom: 26%; width: 6%; height: 6%; border-radius: 50%; background: color-mix(in srgb, var(--accent) 60%, transparent); opacity: 0; animation: vac-dust calc(var(--loader-speed) * 1) ease-in infinite, vac-push calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader i:nth-of-type(1) { left: 26%; }
.loader i:nth-of-type(2) { left: 32%; animation-delay: calc(var(--loader-speed) * .5), 0s; }
@keyframes vac-push { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(calc(var(--loader-size) * .68)); } }
@keyframes vac-clean { 0%, 100% { width: 4%; } 50% { width: 92%; } }
@keyframes vac-dust { 0% { opacity: 0; transform: translate(0, 0) scale(.6); } 25% { opacity: .9; } 100% { opacity: 0; transform: translate(-90%, -50%) scale(1.2); } }
